#[allow(unused_imports)] use cantrip_api::*;
#[allow(unused_variables)] fn ability_0_apply_0(q: &dyn LayerQuery, source: ObjectId, chars: &mut Chars) { let asker = &Asker::new(source, q.controller(source)); for kind in (q.state().battlefield().iter().copied().filter(|&id| (q.chars(id).is(CardType::Land) && Some(asker.controller) == Some(q.controller(id)))).collect::<Vec<ObjectId>>()).into_iter().flat_map(|o: ObjectId| q.chars(o).subtypes.iter()) { if kind.basic_mana().is_some() { if let Some(walk) = Keyword::landwalk(kind) { chars.keywords = chars.keywords.with(walk); } } } }

